import moment from 'moment'
import { formatIntl } from '../../../../../../../helpers/utility'
import { CASE_FORM_FIELDS } from './constants'

export const formValues = (formDataFromState) => {
  const lastHyphenInPhoneIndex = formDataFromState[CASE_FORM_FIELDS.PIC_PHONE]?.lastIndexOf('-')
  const phone = formDataFromState[CASE_FORM_FIELDS.PIC_PHONE]?.substring(lastHyphenInPhoneIndex + 1)
  const values = {
    [CASE_FORM_FIELDS.COMPANY_NAME]: formDataFromState[CASE_FORM_FIELDS.COMPANY_NAME],
    [CASE_FORM_FIELDS.INDUSTRY]: formDataFromState[CASE_FORM_FIELDS.INDUSTRY],
    [CASE_FORM_FIELDS.LINE_OF_BUSINESS]: formDataFromState[CASE_FORM_FIELDS.LINE_OF_BUSINESS],
    [CASE_FORM_FIELDS.AGENT]: formDataFromState[CASE_FORM_FIELDS.AGENT],
    [CASE_FORM_FIELDS.MARKETING]: formDataFromState[CASE_FORM_FIELDS.MARKETING],
    [CASE_FORM_FIELDS.PIC]: formDataFromState[CASE_FORM_FIELDS.PIC],
    [CASE_FORM_FIELDS.PIC_EMAIL]: formDataFromState[CASE_FORM_FIELDS.PIC_EMAIL],
    [CASE_FORM_FIELDS.PIC_PHONE]: phone,
    [CASE_FORM_FIELDS.CHANNEL]: formDataFromState[CASE_FORM_FIELDS.CHANNEL],
    [CASE_FORM_FIELDS.PRODUCT]: formDataFromState[CASE_FORM_FIELDS.PRODUCT],
    [CASE_FORM_FIELDS.TOTAL_PARTICIPANT]: formDataFromState[CASE_FORM_FIELDS.TOTAL_PARTICIPANT],
    [CASE_FORM_FIELDS.BUDGET]: formatIntl(formDataFromState[CASE_FORM_FIELDS.BUDGET]),
    [CASE_FORM_FIELDS.ADD_ON_FEE]: formatIntl(formDataFromState[CASE_FORM_FIELDS.ADD_ON_FEE]),
    [CASE_FORM_FIELDS.SUB_OFFICE]: formDataFromState[CASE_FORM_FIELDS.SUB_OFFICE],
    [CASE_FORM_FIELDS.EXISTING_INSURANCE]: formDataFromState[CASE_FORM_FIELDS.EXISTING_INSURANCE],
    [CASE_FORM_FIELDS.EXISTING_BROKER]: formDataFromState[CASE_FORM_FIELDS.EXISTING_BROKER],
    [CASE_FORM_FIELDS.EFFECTIVE_DATE]: formDataFromState[CASE_FORM_FIELDS.EFFECTIVE_DATE] ? moment(formDataFromState[CASE_FORM_FIELDS.EFFECTIVE_DATE]) : undefined,
    [CASE_FORM_FIELDS.AGENT_COMMISION]: formatIntl(formDataFromState[CASE_FORM_FIELDS.AGENT_COMMISION]),
    [CASE_FORM_FIELDS.PASPOL_COMMISION]: formatIntl(formDataFromState[CASE_FORM_FIELDS.PASPOL_COMMISION]),
    [CASE_FORM_FIELDS.CASE_STATUS]: formDataFromState[CASE_FORM_FIELDS.CASE_STATUS],
    [CASE_FORM_FIELDS.DOCUMENT_RECEIVED]: Array.isArray(formDataFromState[CASE_FORM_FIELDS.DOCUMENT_RECEIVED])
      ? formDataFromState[CASE_FORM_FIELDS.DOCUMENT_RECEIVED].map(url => ({
          name: String(url).split(':')[2],
          uid: url,
          url
        }))
      : []
  }
  return values
}
