import ADD_CASE_ACTIONS from './actions'

export const COMPANY_NAME = 'companyName'

const INITIAL_STATE = {
}

const addCaseReducer = (state, action) => {
  const { payload } = action
  switch (action.type) {
    case ADD_CASE_ACTIONS.ADD_CASE:
    case ADD_CASE_ACTIONS.INDUSTRY:
    case ADD_CASE_ACTIONS.BUSINESS:
    case ADD_CASE_ACTIONS.MARKETING_LIST:
    case ADD_CASE_ACTIONS.UPDATE_CASE:
      return { ...state, ...payload }
    default:
      return state
  }
}

export { INITIAL_STATE }
export default addCaseReducer
