import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useEBContextValue } from '../../../context/index'
import ADD_CASE_ACTIONS from '../actions'

export const useAddCaseApi = () => {
  const [{ addCaseData }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const addCaseRequest = (payload = {}) => {
    callApi(ADD_CASE_ACTIONS.addNewCase({ body: payload }))
  }
  return { addCaseData, addCaseRequest }
}

