/* eslint-disable react-hooks/exhaustive-deps */
import { useErrorContextValue, useLoaderContextValue, useResetError, useGet } from '@pasarpolis/common-react-hooks'
import { Button, Col, DatePicker, Form, Icon, Input, message, Modal, Row, Select, Spin } from 'antd'
import React, { useEffect, useRef, useState } from 'react'
import { useHistory, useParams } from 'react-router'
import FileUploadOnGcsV2 from '../../../../../../../components/FileUploadOnGcsV2'
import PermissionCheckerV2 from '../../../../../../../components/permissionCheckerV2'
import { trimFirstZeroFromPhone } from '../../../../../../../helpers/utility'
import CustomNumberFormat from '../../../../CommonComponents/CustomNumberFormat'
import { useAddCaseApi, useBusiness, useIndustry, useUpdateCase } from '../../../../state/AddNewCase/hooks/useAddNewCase'
import { useLeadConfig, useProviderList, useMarketingList, useDownloadFileFromGcs } from '../../../../state/hooks'
import { horizontalLayout, tailFormItemLayout } from '../../../../utils/formLayout'
import { ebFilesAcceptString } from '../../../../utils/helpers'
import { caseFormApis } from '../../apiConfig'
import { CASE_FORM_FIELDS } from './constants'
import { AntdUploadFullWidthStyled, FormItemStyleWrapper } from './styles'
import { formValues } from './utility'
import { NewCaseFormValidations } from './validations'

const NewCaseForm = ({ form, ...props }) => {
  const { getFieldDecorator, getFieldValue } = form
  const { addCaseData, addCaseRequest } = useAddCaseApi()
  const [detailData, getDetailData] = useGet(caseFormApis.caseDetail)
  const { caseId } = useParams()
  const { updateCaseRequest } = useUpdateCase()
  const [{ ADD_CASE_LOADER, BUSINESS_LOADER, INDUSTRY_LOADER, UPDATE_CASE_LOADER, CASE_DETAIL_LOADER }] = useLoaderContextValue()
  const [{ ADD_CASE_ERROR, addCaseStatus, addCaseErrorData, UPDATE_CASE_ERROR, updateCaseStatus, updateCaseErrorData }] = useErrorContextValue()
  const history = useHistory()
  const { industryData, industryRequest } = useIndustry()
  const { businessData, businessRequest } = useBusiness()
  const { providerListData, providerListRequest } = useProviderList()
  const { marketingListData, marketingListRequest } = useMarketingList()
  const { leadConfigData, leadConfigRequest } = useLeadConfig()
  const { downloadRequest } = useDownloadFileFromGcs()
  const { [CASE_FORM_FIELDS.INDUSTRY]: industry } = form.getFieldsValue()
  const [addMoreCase, setAddMoreCase] = useState(false)
  const { resetError } = useResetError()
  const existingSubOffices = detailData?.[CASE_FORM_FIELDS.SUB_OFFICE]
  const subOfficeKeyLastIndex = useRef(existingSubOffices ? existingSubOffices.length : 0)
  const { [CASE_FORM_FIELDS.MARKETING]: selectedMarketing } = form.getFieldsValue()
  const isThisIndustryChangeFromPreFill = useRef(!!caseId)
  const caseStatus = getFieldValue(CASE_FORM_FIELDS.CASE_STATUS)
  const [quotationList, getQuotationList] = useGet(caseFormApis.quotation_list)
  const isCaseInFinalState = ['CLOSING', 'LOSING'].includes(detailData?.[CASE_FORM_FIELDS.CASE_STATUS])
  const isClosingCaseDataRequired = !(detailData?.[CASE_FORM_FIELDS.CASE_STATUS] === 'CLOSING' && !detailData.mapped_quotation_id)

  getFieldDecorator(CASE_FORM_FIELDS.SUB_OFFICE_KEYS, { initialValue: existingSubOffices ? Object.keys(existingSubOffices) : [0] })

  const addSubOffice = () => {
    const keys = form.getFieldValue(CASE_FORM_FIELDS.SUB_OFFICE_KEYS)
    const nextKeys = keys.concat(++subOfficeKeyLastIndex.current)
    form.setFieldsValue({
      [CASE_FORM_FIELDS.SUB_OFFICE_KEYS]: nextKeys
    })
  }

  const removeSubOffice = k => {
    const keys = form.getFieldValue(CASE_FORM_FIELDS.SUB_OFFICE_KEYS)
    form.setFieldsValue({
      [CASE_FORM_FIELDS.SUB_OFFICE_KEYS]: keys.filter(key => key !== k)
    })
  }

  const handleSubmit = (e) => {
    e.preventDefault()
    form.validateFields((err, values) => {
      if (!err) {
        const toBeSentValues = { ...values }
        toBeSentValues[CASE_FORM_FIELDS.DOCUMENT_RECEIVED] = Array.isArray(toBeSentValues[CASE_FORM_FIELDS.DOCUMENT_RECEIVED])
          ? toBeSentValues[CASE_FORM_FIELDS.DOCUMENT_RECEIVED].map(file => file.url).filter(url => !!url)
          : undefined
        toBeSentValues[CASE_FORM_FIELDS.EFFECTIVE_DATE] = toBeSentValues[CASE_FORM_FIELDS.EFFECTIVE_DATE]
          ? toBeSentValues[CASE_FORM_FIELDS.EFFECTIVE_DATE].format('YYYY-MM-DD')
          : undefined
        toBeSentValues[CASE_FORM_FIELDS.PRODUCT] = toBeSentValues[CASE_FORM_FIELDS.PRODUCT].filter(product => product && String(product).trim())
        toBeSentValues[CASE_FORM_FIELDS.TOTAL_PARTICIPANT] = toBeSentValues[CASE_FORM_FIELDS.TOTAL_PARTICIPANT] ? String(toBeSentValues[CASE_FORM_FIELDS.TOTAL_PARTICIPANT]).split('.').join('').replace(',', '.') : undefined
        toBeSentValues[CASE_FORM_FIELDS.BUDGET] = toBeSentValues[CASE_FORM_FIELDS.BUDGET] ? String(toBeSentValues[CASE_FORM_FIELDS.BUDGET]).split('.').join('').replace(',', '.') : undefined
        toBeSentValues[CASE_FORM_FIELDS.ADD_ON_FEE] = toBeSentValues[CASE_FORM_FIELDS.ADD_ON_FEE] ? String(toBeSentValues[CASE_FORM_FIELDS.ADD_ON_FEE]).split('.').join('').replace(',', '.') : undefined
        toBeSentValues[CASE_FORM_FIELDS.AGENT_COMMISION] = toBeSentValues[CASE_FORM_FIELDS.AGENT_COMMISION] ? String(toBeSentValues[CASE_FORM_FIELDS.AGENT_COMMISION]).split('.').join('').replace(',', '.').replace('%', '') : undefined
        toBeSentValues[CASE_FORM_FIELDS.PASPOL_COMMISION] = toBeSentValues[CASE_FORM_FIELDS.PASPOL_COMMISION] ? String(toBeSentValues[CASE_FORM_FIELDS.PASPOL_COMMISION]).split('.').join('').replace(',', '.').replace('%', '') : undefined
        toBeSentValues[CASE_FORM_FIELDS.PIC_PHONE] = toBeSentValues[CASE_FORM_FIELDS.PIC_PHONE] ? `62-${trimFirstZeroFromPhone(toBeSentValues[CASE_FORM_FIELDS.PIC_PHONE])}` : undefined
        toBeSentValues[CASE_FORM_FIELDS.SUB_OFFICE] = toBeSentValues[CASE_FORM_FIELDS.SUB_OFFICE] ? toBeSentValues[CASE_FORM_FIELDS.SUB_OFFICE].filter(subOffice => !!subOffice) : []
        delete toBeSentValues[CASE_FORM_FIELDS.SUB_OFFICE_KEYS]
        if (caseStatus === 'CLOSING') {
          toBeSentValues[CASE_FORM_FIELDS.SPAK_DOCUMENT] = Array.isArray(toBeSentValues[CASE_FORM_FIELDS.SPAK_DOCUMENT])
            ? toBeSentValues[CASE_FORM_FIELDS.SPAK_DOCUMENT][0]?.url
            : undefined
        } else {
          delete toBeSentValues[CASE_FORM_FIELDS.QUOTATION_ID]
          delete toBeSentValues[CASE_FORM_FIELDS.SPAK_DOCUMENT]
        }
        if (detailData?.id) {
          toBeSentValues.id = detailData.id
          const status = toBeSentValues[CASE_FORM_FIELDS.CASE_STATUS]
          if (['CLOSING', 'LOSING'].includes(status)) {
            const title = status === 'CLOSING' ? 'Please ensure the data are correct' : 'Are you sure?'
            const content = status === 'CLOSING'
              ? 'You will not be able to make any change on some data after closing this case'
              : 'You will not be able to make changes to this case later.'
            Modal.confirm({
              title,
              content,
              onOk: () => updateCaseRequest(toBeSentValues)
            })
          } else {
            updateCaseRequest(toBeSentValues)
          }
        } else {
          addCaseRequest(toBeSentValues)
        }
      }
    })
  }

  const handleFileDownload = (file) => {
    resetError(['DOWNLOAD_FILE_FROM_GCS_ERROR'])
    downloadRequest({
      action_type: 'GET',
      identifier: 'case',
      file_name: file.name
    })
  }

  useEffect(() => {
    if (detailData?.id && caseStatus === 'CLOSING') {
      const url = detailData?.[CASE_FORM_FIELDS.SPAK_DOCUMENT]
      const value = url
        ? [{
            name: String(url).split(':')[2],
            uid: url,
            url
          }]
        : []
      form.setFieldsValue({
        [CASE_FORM_FIELDS.SPAK_DOCUMENT]: value,
        [CASE_FORM_FIELDS.QUOTATION_ID]: detailData.mapped_quotation_id
      })
    }
  }, [caseStatus, detailData])

  useEffect(() => {
    if (ADD_CASE_ERROR && addCaseErrorData) {
      const { error } = addCaseErrorData
      const values = form.getFieldsValue()
      form.setFieldsValue()
      for (const key in error) {
        form.setFields({
          [key]: {
            value: values[key],
            errors: Array.isArray(error[key]) && error[key].map(err => new Error(err))
          }
        })
      }
    }
  }, [ADD_CASE_ERROR, addCaseErrorData])

  useEffect(() => {
    if (UPDATE_CASE_ERROR && updateCaseErrorData) {
      const { error } = updateCaseErrorData
      const values = form.getFieldsValue()
      form.setFieldsValue()
      for (const key in error) {
        form.setFields({
          [key]: {
            value: values[key],
            errors: Array.isArray(error[key]) && error[key].map(err => new Error(err))
          }
        })
      }
    }
  }, [UPDATE_CASE_ERROR, updateCaseErrorData])

  useEffect(() => {
    if (updateCaseStatus === 'success') {
      message.success('Case updated successfully')
      history.push({
        pathname: '/employee-benefits/quotation-data-summary'
      })
    }
  }, [updateCaseStatus])

  useEffect(() => {
    if (addCaseData && addCaseStatus === 'success') {
      message.success('Case added successfully')
      if (addMoreCase) {
        setAddMoreCase(false)
        form.resetFields()
        form.setFieldsValue({
          [CASE_FORM_FIELDS.TOTAL_PARTICIPANT]: '',
          [CASE_FORM_FIELDS.BUDGET]: '',
          [CASE_FORM_FIELDS.AGENT_COMMISION]: '',
          [CASE_FORM_FIELDS.PASPOL_COMMISION]: ''
        })
      } else {
        history.push({
          pathname: '/employee-benefits/add-quotation',
          state: { company_name: form.getFieldValue(CASE_FORM_FIELDS.COMPANY_NAME), case_id: addCaseData.id }
        })
      }
    }
  }, [addCaseData, addCaseStatus])

  useEffect(() => {
    if (selectedMarketing) {
      if (marketingListData && marketingListData.data) {
        const { channel } = marketingListData.data.find((marketing) => marketing.id === selectedMarketing)
        form.setFieldsValue({
          [CASE_FORM_FIELDS.CHANNEL]: channel
        })
      }
    }
  }, [selectedMarketing, marketingListData])

  useEffect(() => {
    if (isThisIndustryChangeFromPreFill.current && industry) {
      isThisIndustryChangeFromPreFill.current = false
    } else if (industry) {
      form.resetFields([CASE_FORM_FIELDS.LINE_OF_BUSINESS])
    }
    if (industry) {
      businessRequest({ industry })
    }
  }, [industry])

  useEffect(() => {
    if (caseId) {
      getQuotationList({
        status: ['WIN', 'ONGOING'],
        case_id: caseId
      })
    }
    if (detailData) {
      form.setFieldsValue({
        ...formValues(detailData)
      })
    }
  }, [detailData])

  useEffect(() => {
    if (caseId) {
      getDetailData({ id: caseId })
    }
    industryRequest()
    marketingListRequest()
    leadConfigRequest()
    providerListRequest()
    return () => resetError([
      'ADD_CASE_ERROR',
      'addCaseErrorData',
      'addCaseStatus',
      'updateCaseData',
      'updateCaseStatus',
      'updateCaseErrorData',
      'UPDATE_CASE_ERROR'
    ])
  }, [caseId, getDetailData])

  return (
    <Spin spinning={!!ADD_CASE_LOADER || !!UPDATE_CASE_LOADER || !!CASE_DETAIL_LOADER}>
      <Form
        {...horizontalLayout}
        onSubmit={handleSubmit}
      >
        <Row gutter={16}>
          <Col span={12}>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='Company Name'
                  required
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.COMPANY_NAME,
                      { rules: NewCaseFormValidations[CASE_FORM_FIELDS.COMPANY_NAME] }
                    )(
                      <Input disabled={isCaseInFinalState} />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='Industry'
                  required
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.INDUSTRY, {
                      rules: NewCaseFormValidations[CASE_FORM_FIELDS.INDUSTRY]
                    }
                    )(
                      <Select
                        loading={!!INDUSTRY_LOADER}
                        disabled={isCaseInFinalState}
                      >
                        {industryData && industryData.industry && industryData.industry.map(industry => (
                          <Select.Option key={industry} value={industry}>{industry}</Select.Option>
                        ))}
                      </Select>
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='Line of Business'
                  required
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.LINE_OF_BUSINESS, {
                      rules: NewCaseFormValidations[CASE_FORM_FIELDS.LINE_OF_BUSINESS]
                    }
                    )(
                      <Select
                        loading={!!BUSINESS_LOADER}
                        disabled={isCaseInFinalState}
                      >
                        {businessData && businessData.business_types && businessData.business_types.map(businessType => (
                          <Select.Option key={businessType} value={businessType}>{businessType}</Select.Option>
                        ))}
                      </Select>
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='Agent/Ref'
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.AGENT, {})(
                      <Input />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='Marketing'
                  required
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.MARKETING, {
                      rules: NewCaseFormValidations[CASE_FORM_FIELDS.MARKETING]
                    })(
                      <Select>
                        {marketingListData && marketingListData.data && marketingListData.data.map(({ name, code, id, email }) => (
                          <Select.Option key={id} value={id}>{email ? `${name}, ${email}` : name}</Select.Option>
                        ))}
                      </Select>
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='PIC'
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.PIC, {
                      rules: NewCaseFormValidations[CASE_FORM_FIELDS.PIC](caseStatus === 'CLOSING' && !(detailData?.id && !detailData?.[CASE_FORM_FIELDS.PIC]))
                    })(
                      <Input disabled={isCaseInFinalState} />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='PIC Phone'
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.PIC_PHONE, {
                      rules: NewCaseFormValidations[CASE_FORM_FIELDS.PIC_PHONE](caseStatus === 'CLOSING' && !(detailData?.id && !detailData?.[CASE_FORM_FIELDS.PIC_PHONE]))
                    })(
                      <Input
                        disabled={isCaseInFinalState}
                        addonBefore='+62'
                      />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='PIC Email'
                  hasFeedback
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.PIC_EMAIL,
                      {
                        rules: NewCaseFormValidations[CASE_FORM_FIELDS.PIC_EMAIL](caseStatus === 'CLOSING' && !(detailData?.id && !detailData?.[CASE_FORM_FIELDS.PIC_EMAIL]))
                      }
                    )(
                      <Input disabled={isCaseInFinalState} />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='Channel'
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.CHANNEL, {})(
                      <Select disabled>
                        {leadConfigData && leadConfigData.channels && leadConfigData.channels.map(({ code, name }) => (
                          <Select.Option key={code} value={code}>{name}</Select.Option>
                        ))}
                      </Select>
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='Product'
                  required
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.PRODUCT, {
                      initialValue: [],
                      rules: NewCaseFormValidations[CASE_FORM_FIELDS.PRODUCT]
                    })(
                      <Select
                        mode='tags'
                        disabled={isCaseInFinalState}
                      >
                        {leadConfigData && leadConfigData.products && leadConfigData.products.map((product, index) => (
                          <Select.Option key={index} value={product.code}>{product.name}</Select.Option>
                        ))}
                      </Select>
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='Total Participant'
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.TOTAL_PARTICIPANT, {
                      rules: NewCaseFormValidations[CASE_FORM_FIELDS.TOTAL_PARTICIPANT]
                    })(
                      <CustomNumberFormat
                        disabled={isCaseInFinalState}
                        decimalScale={0}
                        allowNegative={false}
                        isAllowed={({ floatValue }) => (floatValue >= 0 && floatValue <= 100000) || floatValue === undefined}
                      />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
          </Col>
          <Col span={12}>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='Budget'
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.BUDGET, {
                      rules: NewCaseFormValidations[CASE_FORM_FIELDS.BUDGET]
                    })(
                      <CustomNumberFormat
                        disabled={isCaseInFinalState}
                        decimalScale={3}
                        allowNegative={false}
                        isAllowed={({ floatValue }) => (floatValue >= 0 && floatValue <= 999999999999) || floatValue === undefined}
                      />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            {
              form.getFieldValue(CASE_FORM_FIELDS.SUB_OFFICE_KEYS).map((key, index, array) => (
                <Row key={key}>
                  <Col span={20}>
                    <Form.Item
                      label='Sub Office'
                    >
                      {
                        getFieldDecorator(`${CASE_FORM_FIELDS.SUB_OFFICE}[${key}]`, {})(
                          <Input />
                        )
                      }
                    </Form.Item>
                  </Col>
                  {
                    array.length > 1 && (
                      <Col span={1} offset={1}>
                        <Form.Item>
                          <Button
                            type='link'
                            title='Remove Sub Office'
                            shape='circle'
                            size='small'
                            onClick={() => removeSubOffice(key)}
                          >
                            <Icon
                              type='minus-circle'
                              theme='twoTone'
                              twoToneColor='red'
                            />
                          </Button>
                        </Form.Item>
                      </Col>
                    )
                  }
                  {
                    index === array.length - 1 && (
                      <Col span={1} offset={1}>
                        <Form.Item>
                          <Button
                            type='link'
                            title='Add Another Sub Office'
                            shape='circle'
                            size='small'
                            onClick={addSubOffice}
                          >
                            <Icon
                              type='plus-circle'
                              theme='twoTone'
                              twoToneColor='rgb(50,215,75)'
                            />
                          </Button>
                        </Form.Item>
                      </Col>
                    )
                  }
                </Row>
              ))
            }
            <Row>
              <Col span={20}>
                <Form.Item
                  label='Existing Insurance'
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.EXISTING_INSURANCE, {})(
                      <Select>
                        {providerListData && Array.isArray(providerListData.providers) && (
                          providerListData.providers
                            .sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()))
                            .map(provider => (
                              <Select.Option key={provider} value={provider}>
                                {provider}
                              </Select.Option>
                            ))
                        )}
                      </Select>
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='Existing Broker'
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.EXISTING_BROKER, {})(
                      <Input />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='Effective Date'
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.EFFECTIVE_DATE, {})(
                      <DatePicker
                        disabled={isCaseInFinalState} allowClear
                      />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='Agent Commission %'
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.AGENT_COMMISION)(
                      <CustomNumberFormat
                        decimalScale={3}
                        allowNegative={false}
                        isAllowed={({ floatValue }) => (floatValue >= 0 && floatValue <= 100) || floatValue === undefined}
                      />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='Paspol Commission %'
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.PASPOL_COMMISION)(
                      <CustomNumberFormat
                        decimalScale={3}
                        allowNegative={false}
                        isAllowed={({ floatValue }) => (floatValue >= 0 && floatValue <= 100) || floatValue === undefined}
                      />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='Add On fee'
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.ADD_ON_FEE)(
                      <CustomNumberFormat
                        decimalScale={3}
                        allowNegative={false}
                        isAllowed={({ floatValue }) => (floatValue >= 0 && floatValue <= 999999999999) || floatValue === undefined}
                      />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={20}>
                <AntdUploadFullWidthStyled>
                  <FileUploadOnGcsV2
                    getFieldDecorator={getFieldDecorator}
                    name={CASE_FORM_FIELDS.DOCUMENT_RECEIVED}
                    buttonClassName='fluid-width'
                    form={form}
                    multiple
                    onPreview={handleFileDownload}
                    identifier='case'
                    accept={ebFilesAcceptString}
                    formItemProps={{ label: 'Document Received' }}
                    maxSize={15}
                    minSize={0.001}
                  />
                </AntdUploadFullWidthStyled>
              </Col>
            </Row>
            <Row>
              <Col span={20}>
                <Form.Item
                  label='Case Status'
                  required
                >
                  {
                    getFieldDecorator(CASE_FORM_FIELDS.CASE_STATUS, {
                      rules: NewCaseFormValidations[CASE_FORM_FIELDS.CASE_STATUS]
                    })(
                      <Select disabled={isCaseInFinalState}>
                        {leadConfigData?.case_status?.map(({ code, name }) => (
                          <Select.Option key={code} value={code}>{name}</Select.Option>
                        ))}
                      </Select>
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            {
              caseStatus === 'CLOSING' && (
                <>
                  <Row>
                    <Col span={20}>
                      <AntdUploadFullWidthStyled>
                        <FileUploadOnGcsV2
                          disabled={isCaseInFinalState}
                          getFieldDecorator={getFieldDecorator}
                          name={CASE_FORM_FIELDS.SPAK_DOCUMENT}
                          buttonClassName='fluid-width'
                          form={form}
                          multiple
                          onPreview={handleFileDownload}
                          identifier='case'
                          accept={ebFilesAcceptString}
                          formItemProps={{ label: 'Upload SPAK' }}
                          maxSize={10}
                          minSize={0.001}
                          required={isClosingCaseDataRequired}
                          maxFileAllowed={1}
                        />
                      </AntdUploadFullWidthStyled>
                    </Col>
                  </Row>
                  <Row>
                    <Col span={20}>
                      <FormItemStyleWrapper>
                        <Form.Item
                          label='Select Quotation and the Premi Release'
                          labelAlign='left'
                        >
                          {
                            getFieldDecorator(CASE_FORM_FIELDS.QUOTATION_ID, {
                              rules: NewCaseFormValidations[CASE_FORM_FIELDS.QUOTATION_ID](isClosingCaseDataRequired)
                            })(
                              <Select disabled={isCaseInFinalState}>
                                {
                                  quotationList?.data?.map(quotation => (
                                    <Select.Option
                                      value={quotation.id}
                                      key={quotation.id}
                                    >
                                      {`${quotation?.insurance_provider} (${quotation.id}) / ${quotation.premium ? `Rp ${quotation.premium}` : '-'}`}
                                    </Select.Option>
                                  ))
                                }
                              </Select>
                            )
                          }
                        </Form.Item>

                      </FormItemStyleWrapper>
                    </Col>
                  </Row>
                </>

              )
            }
            {
              caseId
                ? (
                  <Row>
                    <Col span={20}>
                      <Form.Item {...tailFormItemLayout}>
                        <Button
                          type='primary'
                          htmlType='submit'
                          block
                        >
                          Update Case
                          <Icon type='arrow-right' />
                        </Button>
                      </Form.Item>
                    </Col>
                  </Row>
                  )
                : (
                  <PermissionCheckerV2 requiredPermission='ops.eb_create_quotation'>
                    <Row>
                      <Col span={20}>
                        <Form.Item {...tailFormItemLayout}>
                          <Button
                            type='primary'
                            htmlType='submit'
                            block
                          >
                            Continue To Add Quotation Data
                            <Icon type='arrow-right' />
                          </Button>
                        </Form.Item>
                      </Col>
                    </Row>
                  </PermissionCheckerV2>

                  )
            }
            {
              !caseId && (
                <Row>
                  <Col span={20}>
                    <Form.Item {...tailFormItemLayout}>
                      <Button
                        type='primary'
                        htmlType='submit'
                        onClick={() => setAddMoreCase(true)}
                        block
                      >
                        Save And Add Another Case
                      </Button>
                    </Form.Item>
                  </Col>
                </Row>
              )
            }
          </Col>
        </Row>
      </Form>
    </Spin>
  )
}
export default Form.create({ name: 'new-case-form' })(NewCaseForm)
