import React from 'react'
import { Alert } from 'antd'
import EbEmptyPage from '../../../../../../components/EbEmptyPage/ebEmptypage'
import { RowWithMargin } from '../../../CommonComponents'
import NewCaseForm from './components/NewCaseForm'
import { useErrorContextValue } from '@pasarpolis/common-react-hooks'
import { useParams } from 'react-router'

const AddNewCase = ({ history }) => {
  const [{
    ADD_CASE_ERROR,
    addCaseErrorData,
    addCaseStatus,
    UPDATE_CASE_ERROR,
    updateCaseErrorData,
    updateCaseStatus,
    INDUSTRY_ERROR,
    industryStatus,
    BUSINESS_ERROR,
    businessStatus,
    DOWNLOAD_FILE_FROM_GCS_ERROR
  }] = useErrorContextValue()
  const params = useParams()
  const caseId = params?.caseId

  return (
    <EbEmptyPage path='/employee-benefits/quotation-data-summary' history={history}>
      {(ADD_CASE_ERROR && !addCaseErrorData) && <div className='mb-5'><Alert type='error' message={addCaseStatus} banner /></div>}
      {UPDATE_CASE_ERROR && (!updateCaseErrorData) && <div className='mb-5'><Alert type='error' message={updateCaseStatus} banner /></div>}
      {BUSINESS_ERROR && <div className='mb-5'><Alert type='error' message={`Could not load business types, ${businessStatus}`} banner /></div>}
      {INDUSTRY_ERROR && <div className='mb-5'><Alert type='error' message={`Could not load industries, ${industryStatus}`} banner /></div>}
      {DOWNLOAD_FILE_FROM_GCS_ERROR && <div className='mb-5'><Alert type='error' message='Could not download file. Please try again.' banner /></div>}
      <h2 className='text-center'>{caseId ? 'Update Case' : 'Add New Case'}</h2>
      <RowWithMargin />
      <NewCaseForm />
    </EbEmptyPage>
  )
}
export default AddNewCase
