import ebUrls from '../../../../../request/urls/employeeBenefit'

const ADD_CASE_ACTIONS = {

  ADD_CASE_REQUEST: 'ADD_CASE_REQUEST',
  ADD_CASE: 'ADD_CASE',
  INDUSTRY_REQUEST: 'INDUSTRY_REQUEST',
  INDUSTRY: 'INDUSTRY',
  BUSINESS_REQUEST: 'BUSINESS_REQUEST',
  BUSINESS: 'BUSINESS',
  UPDATE_CASE_REQUEST: 'UPDATE_CASE_REQUEST',
  UPDATE_CASE: 'UPDATE_CASE',

  addNewCase: (payload) => ({
    type: ADD_CASE_ACTIONS.ADD_CASE_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.addCase
    }
  }),
  getIndustry: (payload) => ({
    type: ADD_CASE_ACTIONS.INDUSTRY_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getIndustry
    }
  }),
  getBusiness: (payload) => ({
    type: ADD_CASE_ACTIONS.BUSINESS_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getBusinessTypes
    }
  }),
  updateCase: (payload) => ({
    type: ADD_CASE_ACTIONS.UPDATE_CASE_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.updateCase
    }

  })
}

export default ADD_CASE_ACTIONS
